export type Status = 'PENDING' | 'CONFIRMED' | 'CANCELLED' | 'EXPIRED';

export function colour(s: Status): string {
  switch (s) {
    case 'PENDING': return 'amber';
    case 'CANCELLED': return 'grey';
    case 'EXPIRED': return 'slate';
    default: return 'grey';
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { colour } from '../src/colour.ts';

test('pending', () => assert.equal(colour('PENDING'), 'amber'));
test('confirmed', () => assert.equal(colour('CONFIRMED'), 'green'));
test('cancelled', () => assert.equal(colour('CANCELLED'), 'grey'));
test('expired', () => assert.equal(colour('EXPIRED'), 'slate'));

