export type BookingRecord = { id: number; seats: number };

export type BookingState =
  | { step: 'draft' }
  | { step: 'pending'; record: BookingRecord }
  | { step: 'confirmed'; record: BookingRecord };
export type ActiveState = { step: 'pending'; record: BookingRecord } | { step: 'confirmed'; record: BookingRecord };

// asserts s is ActiveState: if it returns, s is narrowed from there on.
export function assertActive(s: BookingState): asserts s is ActiveState {
  if (s.step !== 'pending' && s.step !== 'confirmed') throw new Error('not active: ' + s.step);
}

import { assertActive } from '../src/assert.ts';
import type { BookingState } from '../src/assert.ts';

export function idOf(s: BookingState): number {
  assertActive(s); // after this, s is ActiveState
  return s.record.id;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { idOf } from '../kiem/dung.ts';

const rec = { id: 7, seats: 30 };
test('active', () => assert.equal(idOf({ step: 'confirmed', record: rec }), 7));
test('rejects a draft with the right error', () => assert.throws(() => idOf({ step: 'draft' }), /not active/));

